using System;using System.IO;using System.Linq;using System.Text;using System.Collections.Generic;using System.Reflection;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;using UnityEngine.Rendering;using Unity.Collections;
[InitializeOnLoad]public static class FinalCitywideStops{
const string ScenePath="Assets/Editor/DayNightBackups/Gangstar Final Env.unity",PrefabPath="Assets/Scenes/Oasis/FinalEnvironmentRoads/Final Roads.prefab",Out="Assets/Scenes/Oasis/FinalEnvironmentRoads/RoadDetailAtlas",BusPrefab="Assets/Scenes/Oasis/3D/Prefeb/Bus stop.prefab";
class Surface{public MeshFilter f;public Bounds b;public Vector3[] p;public Vector2[] uv;public Vector4[] mark,site;public int[] ids;public int layer,tile;public float len,width;public bool x;}
class Stop{public Surface road;public Vector3 p,outward;public float fraction,u;}
static FinalCitywideStops(){EditorApplication.update+=Poll;}static void Poll(){if(!File.Exists("FinalCitywideStops.request")||EditorApplication.isCompiling||EditorApplication.isPlayingOrWillChangePlaymode)return;var mode=File.ReadAllText("FinalCitywideStops.request").Trim();File.Delete("FinalCitywideStops.request");if(mode=="verify"){Verify();return;}Run(mode);}
static void Verify(){var log=new StringBuilder();try{var scene=SceneManager.GetSceneByPath(ScenePath);var root=scene.GetRootGameObjects().Single(g=>g.name=="Track Roads");var group=root.transform.Find("Citywide Bus Stops - 20");if(!group||group.GetComponentsInChildren<MeshRenderer>(true).Length!=20)throw new Exception("Shelter count wrong");var all=root.GetComponentsInChildren<MeshFilter>(true).Where(f=>f.sharedMesh&&f.GetComponent<Renderer>()&&f.GetComponent<Renderer>().sharedMaterial&&f.GetComponent<Renderer>().sharedMaterial.name=="City PNG Markings").Select(Read).ToArray();var bus=all.Where(r=>r.site!=null&&r.site.Any(v=>Mathf.RoundToInt(v.z)==21&&v.w<0)).ToArray();var noParking=all.Where(r=>r.site!=null&&r.site.Any(v=>Mathf.RoundToInt(v.z)==19&&v.w<0)).ToArray();if(bus.Length!=20||noParking.Length!=10)throw new Exception("Road patch counts "+bus.Length+","+noParking.Length);var unmarked=all.Where(r=>(r.layer==0||r.layer==2)&&r.len>35&&r.width>8&&r.width<40&&r.mark==null).ToArray();if(unmarked.Length>0)throw new Exception("Unmarked road sections remain");int errors=all.Select(r=>r.f.GetComponent<Renderer>().sharedMaterial.shader).Distinct().Sum(s=>ShaderUtil.GetShaderMessages(s).Count(m=>m.severity.ToString()=="Error"));if(errors>0)throw new Exception("Shader errors");for(int i=0;i<3;i++){var stop=group.GetChild(i);var nearest=bus.OrderBy(r=>r.b.SqrDistance(stop.position)).First();var dir=nearest.x?Vector3.right:Vector3.forward;var outward=stop.position-nearest.b.center;outward.y=0;outward=nearest.x?new Vector3(0,0,Mathf.Sign(outward.z)):new Vector3(Mathf.Sign(outward.x),0,0);Photo(scene,stop.position-outward*15+dir*8+Vector3.up*9,stop.position,"Citywide-Bus-"+(i+1));}foreach(var r in noParking.Take(2))Photo(scene,r.b.center+Vector3.up*32,r.b.center,"Road-NoParking-"+r.f.name);foreach(var name in new[]{"polySurface853","polySurface959"}){var r=all.FirstOrDefault(s=>s.f.name==name);if(r!=null)Photo(scene,r.b.center+Vector3.up*30,r.b.center,"Consistent-Road-"+name);}foreach(var module in root.GetComponentsInChildren<Transform>(true).Where(t=>t.name.StartsWith("Sunken Underpass "))){var f=module.GetComponentsInChildren<MeshFilter>(true).First(v=>v.name=="Continuous underpass roadway");var r=all.Single(s=>s.f==f);var p=r.b.center;var d=r.x?Vector3.right:Vector3.forward;Photo(scene,p-d*(r.len*.37f)+Vector3.up*4,p-d*(r.len*.47f),"Clean-Underpass-Approach-"+module.name.Replace(" ","_"));}
log.AppendLine("SUCCESS: 20 bus-stop prefab renderers; 20 matching BUS STOP PNG bays; 10 road NO PARKING patches; all eligible road sections mapped; shader errors=0. Complete integer repeat patterns prevent cropped end fragments.");}catch(Exception e){log.AppendLine("FAILED "+e);Debug.LogException(e);}File.WriteAllText("FinalEnvironmentRoadReview/CitywideStops-verification.txt",log.ToString());}
static Surface Read(MeshFilter f){var s=new Surface{f=f,b=f.GetComponent<Renderer>().bounds};s.len=Mathf.Max(s.b.size.x,s.b.size.z);s.width=Mathf.Min(s.b.size.x,s.b.size.z);s.x=s.b.size.x>s.b.size.z;using(var all=MeshUtility.AcquireReadOnlyMeshData(f.sharedMesh)){var d=all[0];using(var a=new NativeArray<Vector3>(d.vertexCount,Allocator.Temp)){d.GetVertices(a);s.p=a.ToArray().Select(f.transform.TransformPoint).ToArray();}using(var a=new NativeArray<Vector2>(d.vertexCount,Allocator.Temp)){if(d.HasVertexAttribute(VertexAttribute.TexCoord0)){d.GetUVs(0,a);s.uv=a.ToArray();}}foreach(int c in new[]{3,4})if(d.HasVertexAttribute((VertexAttribute)((int)VertexAttribute.TexCoord0+c)))using(var a=new NativeArray<Vector4>(d.vertexCount,Allocator.Temp)){d.GetUVs(c,a);if(c==3)s.mark=a.ToArray();else s.site=a.ToArray();}var ids=new List<int>();for(int k=0;k<d.subMeshCount;k++)using(var a=new NativeArray<int>(d.GetSubMesh(k).indexCount,Allocator.Temp)){d.GetIndices(a,k);ids.AddRange(a.ToArray());}s.ids=ids.ToArray();}s.layer=s.uv==null?-1:Mathf.FloorToInt(s.uv.Average(v=>v.x)/32);s.tile=s.mark==null?-1:Mathf.FloorToInt(s.mark[0].x/32);return s;}
static bool Height(Surface s,Vector3 q,out float y){y=0;float best=1;bool found=false;if(q.x<s.b.min.x||q.x>s.b.max.x||q.z<s.b.min.z||q.z>s.b.max.z)return false;for(int k=0;k<s.ids.Length;k+=3){var a=s.p[s.ids[k]];var b=s.p[s.ids[k+1]];var c=s.p[s.ids[k+2]];float ax=b.x-a.x,az=b.z-a.z,bx=c.x-a.x,bz=c.z-a.z,px=q.x-a.x,pz=q.z-a.z,det=ax*bz-az*bx;if(Mathf.Abs(det)<.00001f)continue;float u=(px*bz-pz*bx)/det,v=(ax*pz-az*px)/det;if(u<0||v<0||u+v>1)continue;float h=a.y+u*(b.y-a.y)+v*(c.y-a.y);if(Mathf.Abs(h-q.y)<best){best=Mathf.Abs(h-q.y);y=h;found=true;}}return found;}
static bool Pavement(Surface[] floors,Vector3 p,out float y){y=0;float best=1;bool hit=false;foreach(var f in floors)if(Height(f,p,out float h)&&Mathf.Abs(h-p.y)<best){best=Mathf.Abs(h-p.y);y=h;hit=true;}return hit;}
static Vector4[] Map(Surface r){float u0=r.uv.Min(v=>v.x),u1=r.uv.Max(v=>v.x);float lo=r.x?r.b.min.x:r.b.min.z,hi=r.x?r.b.max.x:r.b.max.z;int tile=r.layer==2?2:0;float rep=Mathf.Max(1,Mathf.Round(r.len/(tile==2?60:40)));var uv=r.p.Select((p,i)=>new Vector4(tile*32+16+Mathf.Clamp(Mathf.InverseLerp(u0,u1,r.uv[i].x),.00001f,.99999f),Mathf.InverseLerp(lo,hi,r.x?p.x:p.z)*rep,Mathf.InverseLerp(lo,hi,r.x?p.x:p.z),rep)).ToArray();float sign=0;for(int k=0;k<r.ids.Length;k+=3){int a=r.ids[k],b=r.ids[k+1],c=r.ids[k+2];var p=r.p[b]-r.p[a];var q=r.p[c]-r.p[a];var u=uv[b]-uv[a];var v=uv[c]-uv[a];float det=u.x*v.y-u.y*v.x;if(Mathf.Abs(det)>.00001f){sign=(p.x*q.z-p.z*q.x)/det;break;}}if(sign<0)for(int i=0;i<uv.Length;i++){uv[i].y=rep-uv[i].y;uv[i].z=1-uv[i].z;}return uv;}
static List<Stop> Plan(Surface[] roads,Surface[] floors,Renderer[] original,GameObject source){var candidates=new List<Stop>();var existing=original.Where(r=>PrefabUtility.GetPrefabAssetPathOfNearestInstanceRoot(r.gameObject)==BusPrefab).Select(r=>r.bounds.center).ToArray();var junctions=roads.Where(r=>r.layer==1||r.tile>=8&&r.tile<=12).ToArray();foreach(var r in roads.Where(r=>r.layer==0&&r.len>65&&r.width>22&&r.width<36&&r.b.size.y<.25f&&(r.tile<0||r.tile==0)&&!(r.site!=null&&r.site.Any(v=>v.w<-.5))))foreach(float t in new[]{.3f,.5f,.7f})foreach(int side in new[]{-1,1}){var dir=r.x?Vector3.right:Vector3.forward;var outward=(r.x?Vector3.forward:Vector3.right)*side;var edge=r.b.center+dir*((t-.5f)*r.len)+outward*(r.width/2);var p=edge+outward*2.25f;if(existing.Any(v=>Horizontal(v,p)<85)||junctions.Any(j=>Horizontal(j.b.center,p)<35))continue;if(!Pavement(floors,p,out float y)||Mathf.Abs(y-edge.y)>.4)continue;p.y=y;bool okay=true;foreach(float ds in new[]{-2.5f,0,2.5f})foreach(float dd in new[]{-.85f,.85f}){var q=p+dir*ds+outward*dd;if(!Pavement(floors,q,out float h)||Mathf.Abs(h-y)>.12f)okay=false;}if(!okay)continue;var occupied=new Bounds(p+Vector3.up*1.7f,r.x?new Vector3(5,3.3f,1.8f):new Vector3(1.8f,3.3f,5));foreach(var other in original){var b=other.bounds;if(other.transform.IsChildOf(r.f.transform)||b.size.y<.5||b.size.x>230||b.size.z>230||other.name.Contains("Canal")||other.name.Contains("Outer_MEsh"))continue;if(b.Intersects(occupied)){okay=false;break;}}if(!okay)continue;int nearest=Enumerable.Range(0,r.p.Length).OrderBy(i=>Vector3.SqrMagnitude(r.p[i]-edge)).First();float u=(r.mark??Map(r))[nearest].x-(r.tile<0?(r.layer==2?2:0):r.tile)*32-16;candidates.Add(new Stop{road=r,p=p,outward=outward,fraction=t,u=u<.5f?.135f:.895f});}var selected=new List<Stop>();while(selected.Count<20&&candidates.Count>0){var pick=candidates.OrderByDescending(c=>selected.Count==0?existing.DefaultIfEmpty(Vector3.zero).Min(v=>Horizontal(v,c.p)):selected.Min(v=>Horizontal(v.p,c.p))).First();selected.Add(pick);candidates.RemoveAll(c=>c.road==pick.road||Horizontal(c.p,pick.p)<90);}return selected;}
static float Horizontal(Vector3 a,Vector3 b)=>Vector2.Distance(new Vector2(a.x,a.z),new Vector2(b.x,b.z));
static void Run(string mode){var log=new StringBuilder();try{var scene=SceneManager.GetSceneByPath(ScenePath);var root=scene.GetRootGameObjects().Single(g=>g.name=="Track Roads");var renderers=scene.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Renderer>(true)).Where(r=>r.enabled&&r.gameObject.activeInHierarchy).ToArray();var roadFilters=root.GetComponentsInChildren<MeshFilter>(true).Where(f=>f.sharedMesh&&f.GetComponent<Renderer>()&&f.GetComponent<Renderer>().sharedMaterial&&new[]{"Road Atlas","City PNG Markings"}.Contains(f.GetComponent<Renderer>().sharedMaterial.name)).ToArray();var all=roadFilters.Select(Read).ToArray();var roads=all.Where(s=>s.layer==0||s.layer==1||s.layer==2).ToArray();var extraFloors=renderers.Where(r=>r.GetComponent<MeshFilter>()&&r.GetComponent<MeshFilter>().sharedMesh&&r.bounds.size.y<6&&r.sharedMaterial&&r.sharedMaterial.name.ToLowerInvariant().Contains("pathway")).Select(r=>Read(r.GetComponent<MeshFilter>())).ToArray();var floors=all.Where(s=>s.layer==3).Concat(extraFloors).ToArray();var source=renderers.Where(r=>r.name=="Bus stop").Select(r=>r.gameObject).FirstOrDefault()??renderers.Where(r=>PrefabUtility.GetPrefabAssetPathOfNearestInstanceRoot(r.gameObject)==BusPrefab).Select(r=>r.gameObject).First();var stops=Plan(roads,floors,renderers,source);log.AppendLine("Pavement surfaces="+floors.Length+"; valid separated shelter positions="+stops.Count+"; source="+source.name+" scale="+source.transform.lossyScale+" rotation="+source.transform.eulerAngles);foreach(var r in roads.Where(s=>(s.layer==0||s.layer==2)&&s.len>35&&s.width>8&&s.width<40))log.AppendLine("ROAD "+r.f.name+" layer="+r.layer+" tile="+r.tile+" width="+r.width+" len="+r.len+" y="+r.b.size.y+" has site="+(r.site!=null&&r.site.Any(v=>v.w<-.5)));foreach(var s in stops)log.AppendLine("STOP "+s.road.f.name+" "+s.p+" outward="+s.outward+" u="+s.u+" fraction="+s.fraction);if(mode=="build"){if(stops.Count!=20)throw new Exception("Expected 20 valid shelters");Build(scene,root,roads,stops,source,log);}else log.AppendLine("AUDIT COMPLETE");}catch(Exception e){log.AppendLine("FAILED "+e);Debug.LogException(e);}File.WriteAllText("FinalEnvironmentRoadReview/CitywideStops-"+mode+".txt",log.ToString());}
static Mesh SaveMesh(Mesh m,string name){m.name=name;string path=Out+"/Meshes/"+name+".asset";var old=AssetDatabase.LoadAssetAtPath<Mesh>(path);if(old){EditorUtility.CopySerialized(m,old);UnityEngine.Object.DestroyImmediate(m);EditorUtility.SetDirty(old);return old;}AssetDatabase.CreateAsset(m,path);return m;}
static Vector4[] Site(Surface r,int code,float u,float t,float width,float length){int tile=Mathf.FloorToInt(r.mark[0].x/32);int min=Enumerable.Range(0,r.p.Length).OrderBy(i=>r.x?r.p[i].x:r.p[i].z).First();int max=Enumerable.Range(0,r.p.Length).OrderByDescending(i=>r.x?r.p[i].x:r.p[i].z).First();float centre=Mathf.Lerp(r.mark[min].y/r.mark[min].w,r.mark[max].y/r.mark[max].w,t);return r.mark.Select(v=>{float a=(v.x-tile*32-16-u)/width+.5f;float b=(v.y/v.w-centre)/(length/r.len)+.5f;if(u>.5f){a=1-a;b=1-b;}return new Vector4(a,b,code,-1);}).ToArray();}
static void Photo(Scene scene,Vector3 p,Vector3 target,string name){typeof(FinalPNGCityDetails).GetMethod("Capture",BindingFlags.Static|BindingFlags.NonPublic).Invoke(null,new object[]{scene,p,target,name});}
static void Build(Scene scene,GameObject root,Surface[] roads,List<Stop> stops,GameObject source,StringBuilder log){
if(root.GetComponentsInChildren<Transform>(true).Any(t=>t.name=="Citywide Bus Stops - 20"))throw new Exception("Bus-stop expansion already exists; do not duplicate.");
string stamp=DateTime.UtcNow.ToString("yyyyMMdd-HHmmss");EditorSceneManager.SaveScene(scene,"FinalEnvironmentRoadBackup/BeforeCitywideStops-"+stamp+".unity",true);File.Copy(PrefabPath,"FinalEnvironmentRoadBackup/BeforeCitywideStops-"+stamp+".prefab");
var eligible=roads.Where(r=>(r.layer==0||r.layer==2)&&r.len>35&&r.width>8&&r.width<40&&r.f.sharedMesh.subMeshCount==1).ToArray();var changes=new Dictionary<MeshFilter,Mesh>();var paint=AssetDatabase.LoadAssetAtPath<Material>(Out+"/City PNG Markings.mat");int extended=0,regularised=0;
foreach(var r in eligible){var m=UnityEngine.Object.Instantiate(r.f.sharedMesh);if(r.mark==null){r.mark=Map(r);r.tile=Mathf.FloorToInt(r.mark[0].x/32);extended++;}else{r.mark=(Vector4[])r.mark.Clone();float old=r.mark[0].w;float rep=Mathf.Max(1,Mathf.Round(old));if(r.tile==5)rep=Mathf.Max(1,Mathf.Round(r.len/35));if(old>0){for(int i=0;i<r.mark.Length;i++){r.mark[i].y=r.mark[i].y/old*rep;r.mark[i].w=rep;}regularised++;}}m.SetUVs(3,r.mark.ToList());changes.Add(r.f,m);}
foreach(var stop in stops){if(!changes.TryGetValue(stop.road.f,out var m))throw new Exception("Shelter road missing");m.SetUVs(4,Site(stop.road,21,stop.u,stop.fraction,.17f,14).ToList());}
var noParking=eligible.Where(r=>r.layer==0&&r.tile==0&&r.len>65&&r.b.size.y<.25f&&!stops.Any(s=>s.road==r)&&!(r.site!=null&&r.site.Any(v=>v.w<-.5))).ToList();var picked=new List<Surface>();while(picked.Count<10&&noParking.Count>0){var r=noParking.OrderByDescending(s=>picked.Count==0?s.b.center.sqrMagnitude:picked.Min(p=>Horizontal(p.b.center,s.b.center))).First();picked.Add(r);noParking.RemoveAll(s=>s==r||Horizontal(s.b.center,r.b.center)<65);}if(picked.Count!=10)throw new Exception("Not enough no-parking roads");for(int k=0;k<picked.Count;k++){var r=picked[k];changes[r.f].SetUVs(4,Site(r,19,k%2==0?.135f:.895f,k%2==0?.3f:.7f,.15f,9).ToList());log.AppendLine("ROAD NO PARKING "+r.f.name+" "+r.b.center);}
foreach(var r in eligible){var before=Read(r.f);var mesh=changes[r.f];if(mesh.vertexCount!=before.p.Length)throw new Exception("Road vertex count changed");using(var md=MeshUtility.AcquireReadOnlyMeshData(mesh))using(var a=new NativeArray<Vector3>(md[0].vertexCount,Allocator.Temp)){md[0].GetVertices(a);var vertices=a.ToArray().Select(r.f.transform.TransformPoint).ToArray();if(!vertices.SequenceEqual(before.p))throw new Exception("Road geometry changed: "+r.f.name);}changes[r.f]=SaveMesh(mesh,"PNG_Consistent_"+r.f.name.Replace(" ","_")+"_"+Mathf.Abs(r.f.GetInstanceID()));}
var nearest=roads.Where(r=>r.layer==0||r.layer==2).OrderBy(r=>r.b.SqrDistance(source.GetComponent<Renderer>().bounds.center)).First();var templateCentre=source.GetComponent<Renderer>().bounds.center;Vector3 inward=nearest.b.center-templateCentre;inward.y=0;inward=nearest.x?new Vector3(0,0,Mathf.Sign(inward.z)):new Vector3(Mathf.Sign(inward.x),0,0);var prefab=PrefabUtility.LoadPrefabContents(PrefabPath);try{
foreach(var c in changes){var path=AnimationUtility.CalculateTransformPath(c.Key.transform,root.transform);var target=prefab.transform.Find(path);if(!target)throw new Exception("Prefab road missing "+path);target.GetComponent<MeshFilter>().sharedMesh=c.Value;target.GetComponent<MeshRenderer>().sharedMaterial=paint;}
var group=new GameObject("Citywide Bus Stops - 20");group.transform.SetParent(prefab.transform,false);var asset=AssetDatabase.LoadAssetAtPath<GameObject>(BusPrefab);int index=0;foreach(var stop in stops){var go=(GameObject)PrefabUtility.InstantiatePrefab(asset,group.transform);go.name="Bus stop - City "+(++index).ToString("D2")+" - "+stop.road.f.name;float yaw=Vector3.SignedAngle(inward,-stop.outward,Vector3.up);go.transform.SetPositionAndRotation(stop.p,Quaternion.AngleAxis(yaw,Vector3.up)*source.transform.rotation);go.transform.localScale=source.transform.lossyScale;var mr=go.GetComponent<MeshRenderer>();go.GetComponent<MeshFilter>().sharedMesh=source.GetComponent<MeshFilter>().sharedMesh;mr.sharedMaterials=source.GetComponent<MeshRenderer>().sharedMaterials;var b=mr.bounds;go.transform.position+=new Vector3(stop.p.x-b.center.x,stop.p.y-b.min.y+.01f,stop.p.z-b.center.z);GameObjectUtility.SetStaticEditorFlags(go,GameObjectUtility.GetStaticEditorFlags(source));if(Mathf.Abs(mr.bounds.min.y-stop.p.y-.01f)>.025f)throw new Exception("Shelter not grounded");if(go.GetComponentsInChildren<Light>(true).Length>0)throw new Exception("Unexpected shelter lights");log.AppendLine("PLACED "+go.name+" base="+mr.bounds.min+" bounds="+mr.bounds);}
PrefabUtility.SaveAsPrefabAsset(group,Out+"/Citywide Bus Stops.prefab",out bool propsOkay);if(!propsOkay)throw new Exception("Shelter prefab save failed");PrefabUtility.SaveAsPrefabAsset(prefab,PrefabPath,out bool okay);if(!okay)throw new Exception("Road prefab save failed");
}finally{PrefabUtility.UnloadPrefabContents(prefab);}
foreach(var c in changes){c.Key.sharedMesh=c.Value;c.Key.GetComponent<MeshRenderer>().sharedMaterial=paint;PrefabUtility.RecordPrefabInstancePropertyModifications(c.Key);PrefabUtility.RecordPrefabInstancePropertyModifications(c.Key.GetComponent<MeshRenderer>());}
var groupInScene=root.transform.Find("Citywide Bus Stops - 20");if(!groupInScene){var g=(GameObject)PrefabUtility.InstantiatePrefab(AssetDatabase.LoadAssetAtPath<GameObject>(Out+"/Citywide Bus Stops.prefab"),root.transform);g.name="Citywide Bus Stops - 20";groupInScene=g.transform;}int count=groupInScene.GetComponentsInChildren<MeshRenderer>(true).Length;if(count!=20)throw new Exception("Shelter scene count="+count);
AssetDatabase.SaveAssets();EditorSceneManager.MarkSceneDirty(scene);if(!EditorSceneManager.SaveScene(scene))throw new Exception("Scene save failed");int errors=ShaderUtil.GetShaderMessages(paint.shader).Count(m=>m.severity.ToString()=="Error");if(errors>0)throw new Exception("Shader errors="+errors);
for(int i=0;i<Mathf.Min(3,stops.Count);i++){var s=stops[i];var dir=s.road.x?Vector3.right:Vector3.forward;Photo(scene,s.p-stopOut(s)*15+dir*8+Vector3.up*9,s.p,"Citywide-Bus-"+(i+1));}foreach(var r in picked.Take(2))Photo(scene,r.b.center+Vector3.up*32,r.b.center,"Road-NoParking-"+r.f.name);foreach(var r in eligible.Where(r=>r.tile==5).Take(1))Photo(scene,r.b.center+Vector3.up*28,r.b.center,"Centred-ONLY-"+r.f.name);
log.AppendLine("SUCCESS: 20 grounded bus-stop prefab instances with 20 matching BUS STOP PNG bays; 10 road NO PARKING patches; missing road markings added="+extended+"; complete-pattern road layouts="+regularised+"; geometry and colliders unchanged; scene and prefabs saved; shader errors=0.");
}
static Vector3 stopOut(Stop s)=>s.outward;
}


